import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ModernCounterProps = Record<string, any>;

const ModernCounter: React.FC<ModernCounterProps> = ({
  backgroundColor = "#4292C6",
  transparentBackground = false,
  durationInSeconds = 5,
  bufferInSeconds = 1.0,
  targetValue = 90757,
  startValue = 500,
  prefix = "$",
  suffix = "",
  fontSize = 280,
  textColor = "#ffffff",
  showShadow = false,
}) => {
  // Load geometric fallbacks similar to Century Gothic
  useFontLoader(["Outfit", "Questrial"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Timing Calculations
  const totalFrames = durationInSeconds * fps;
  const bufferFrames = bufferInSeconds * fps;
  // Ensure animation always runs for at least 1 frame to prevent division errors
  const animationDurationFrames = Math.max(1, totalFrames - bufferFrames);
  
  // Interpolate the numeric value
  // We use a custom bezier easing for a premium "slot machine" slowdown feel
  const progress = interpolate(
    frame,
    [0, animationDurationFrames],
    [0, 1],
    {
      easing: Easing.bezier(0.12, 0.77, 0.23, 0.98), // Smooth exponential ease-out
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp", // This holds the value at the end (buffer)
    }
  );

  const currentValue = interpolate(
    progress,
    [0, 1],
    [startValue, targetValue]
  );

  // Entrance Animation (Scale & Opacity)
  const entranceDriver = spring({
    frame,
    fps,
    config: { damping: 12, stiffness: 100 }
  });
  
  const opacity = interpolate(entranceDriver, [0, 1], [0, 1], { extrapolateRight: "clamp" });
  const scale = interpolate(entranceDriver, [0, 1], [0.8, 1], { extrapolateRight: "clamp" });
  const translateY = interpolate(entranceDriver, [0, 1], [50, 0], { extrapolateRight: "clamp" });

  // Add a subtle "bump" when the counter finishes or nears end
  const finishBumpStart = animationDurationFrames * 0.9;
  const finishBump = spring({
    frame: frame - finishBumpStart, // Start bumping near the end of the counting phase
    fps,
    config: { damping: 10, stiffness: 200 }
  });
  
  // Combine scales: Main entrance + subtle finish impact
  const finalScale = scale + interpolate(finishBump, [0, 1], [0, 0.02]); 

  // Format the number
  const formattedNumber = new Intl.NumberFormat("en-US", {
    maximumFractionDigits: 0,
    minimumFractionDigits: 0,
  }).format(Math.round(currentValue));

  const textStyle: React.CSSProperties = {
    fontFamily: "Century Gothic, Outfit, Questrial, sans-serif",
    fontWeight: "bold",
    fontSize: fontSize,
    color: textColor,
    fontVariantNumeric: "tabular-nums", // Crucial for counters to prevent jitter
    letterSpacing: "-0.04em",
    textAlign: "center",
    lineHeight: 1,
    textShadow: showShadow 
      ? "0px 10px 40px rgba(0,0,0,0.5)" 
      : "none",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Century Gothic, Outfit, Questrial, sans-serif",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          alignItems: "baseline",
          gap: fontSize * 0.05,
          opacity,
          transform: `scale(${finalScale}) translateY(${translateY}px)`,
        }}
      >
        {prefix && (
          <span style={{ ...textStyle, fontSize: fontSize * 0.85, opacity: 0.9 }}>
            {prefix}
          </span>
        )}
        
        <span style={textStyle}>
          {formattedNumber}
        </span>

        {suffix && (
          <span style={{ ...textStyle, fontSize: fontSize * 0.6, opacity: 0.8 }}>
            {suffix}
          </span>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default ModernCounter;